// As returns a handle that references ai_training_export_records under its own alias.
func (t *TrainingExportRecordsTable) As(alias string) *TrainingExportRecordsTable {
	return keel.Alias(t.Ref, alias, BuildTrainingExportRecords)
}

// Get returns the ai_training_export_records row with the given key, or keel.ErrNotFound.
func (t *TrainingExportRecordsTable) Get(ctx context.Context, db *keel.DB, key pulid.ID) (*aitraining.TrainingExportRecord, error) {
	return t.Where(t.ID.Eq(key)).One(ctx, db)
}

func newTrainingExportRecord() unsafe.Pointer {
	return unsafe.Pointer(new(aitraining.TrainingExportRecord))
}

func newNTrainingExportRecord(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]aitraining.TrainingExportRecord, n)))
}

func ptrTrainingExportRecord(p unsafe.Pointer, c int32) any {
	r := (*aitraining.TrainingExportRecord)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ExportID))
	case 4:
		return (*string)(unsafe.Pointer(&r.CorrectionID))
	case 5:
		return &r.ExampleID
	case 6:
		return (*string)(unsafe.Pointer(&r.Split))
	case 7:
		return &r.ConsentGrantedAt
	case 8:
		return &r.ExportedAt
	case 9:
		return &r.CreatedAt
	}
	return nil
}

func valueTrainingExportRecord(p unsafe.Pointer, c int32) any {
	r := (*aitraining.TrainingExportRecord)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ExportID)
	case 4:
		return string(r.CorrectionID)
	case 5:
		return r.ExampleID
	case 6:
		return string(r.Split)
	case 7:
		return r.ConsentGrantedAt
	case 8:
		return r.ExportedAt
	case 9:
		return r.CreatedAt
	}
	return nil
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

